C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -NoProfile -Command "`$nodes=@('SH_AR','PE2','PE1','BJHQ_CSR1000V_GW_01','FW_01','FW_02','Core_SW_01','Core_SW_02')
foreach(`$n in `$nodes){
  `$cmd=if(`$n -eq 'BJHQ_CSR1000V_GW_01'){'show%20running-config'}else{'display%20current-configuration'}
  `$u4='http://127.0.0.1:3080/v3/projects/CampusNetwork_04/nodes/'+`$n+'/command?cmd='+`$cmd
  `$u5='http://127.0.0.1:3080/v3/projects/CampusNetwork_05/nodes/'+`$n+'/command?cmd='+`$cmd
  `$a=(Invoke-RestMethod -Uri `$u4).output -split '\r?\n'
  `$b=(Invoke-RestMethod -Uri `$u5).output -split '\r?\n'
  `$d=Compare-Object `$a `$b | Where-Object {`$_.InputObject -notmatch 'Last configuration|snmp-agent local-engineid|Current configuration :|certificate|license udi|Software Version|Last configuration change'}
  if(`$d){[pscustomobject]@{node=`$n;diff=`$d} | ConvertTo-Json -Depth 6}
}"

